mapper.sql:
WHERE DEL_YN = 'N'

	AND TRMS_TYPE_CD = #{termsTypeCd}


	AND CURRENT_YN = #{currentYn}


	AND DATE(REG_DT) >= #{startRegDate}


	AND DATE(REG_DT) <= #{endRegDate}




			AND TRMS_CN LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (TRMS_TTL LIKE CONCAT('%', #{searchKeyword}, '%')
				OR TRMS_CN LIKE CONCAT('%', #{searchKeyword}, '%'))


			AND TRMS_TTL LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.insert:
INSERT INTO HMPG_TERMS (
	TRMS_TYPE_CD, TRMS_TYPE_NM, TRMS_TTL, TRMS_CN, CURRENT_YN, DEL_YN,
	REG_DT, RGTR, RGTR_NM, MDFCN_DT, MDTR
) VALUES (
	#{trmsTypeCd}, #{trmsTypeNm}, #{trmsTtl}, #{trmsCn}, #{currentYn}, 'N',
	NOW(), #{rgtr}, #{rgtrNm}, NOW(), #{mdtr}
)

mapper.update:
UPDATE HMPG_TERMS
SET CURRENT_YN = 'N',
	MDFCN_DT = NOW()
WHERE DEL_YN = 'N'
	AND TRMS_TYPE_CD = #{trmsTypeCd}

		AND TRMS_SN != #{exceptTrmsSn}

UPDATE HMPG_TERMS
SET DEL_YN = 'Y',
	DEL_DT = NOW(),
	DELTR = #{deltr}
WHERE TRMS_SN = #{trmsSn}
	AND DEL_YN = 'N'
